    about_devices_link: "На яких e-reader перевірено PaperGames - і як перевірити ваш",
    devices_intro: "PaperGames працює у веббраузері e-reader. На яких пристроях він справді працює, відомо лише там, де хтось спробував і повідомив про це. На цій сторінці перелічено ці пристрої, і так само чітко сказано, що не перевірялося.",
