    devices_untested: "Усі інші пристрої не перевірені. PaperGames цілком може на них працювати, але поки що ніхто про це не повідомив.",
    devices_requirements: "PaperGames потребує сучасного браузера з підтримкою JavaScript ES2015 (const, стрілкові функції, проміси), fetch, Flexbox і змінних CSS, а також service worker для гри офлайн. Наскільки відомо, старіший браузер Kindle і браузер Kobo на основі Qt WebKit 538 цього не вміють; там PaperGames показує лише коротке повідомлення.",
    devices_check_title: "Перевірте на своєму пристрої",
    devices_step1_title: "1. Відкрити сторінку",
    devices_step1_text: "Відкрийте PaperGames у вбудованому браузері вашого e-reader. Зверніть увагу: сторінка завантажується, текст чіткий і нічого не обрізано по краях.",
    devices_step2_title: "2. Почати гру",
    devices_step2_text: "Почніть гру, наприклад Судоку або Шахи, і зробіть кілька ходів. Зверніть увагу: кожне натискання влучає в потрібну клітинку, а дошка вміщується на екрані без прокручування вбік.",
    devices_step3_title: "3. Відкрити налаштування",
    devices_step3_text: "Відкрийте Налаштування й перемкніть розмір тексту та високий контраст. Зверніть увагу: сторінка одразу змінюється, і все залишається читабельним.",
    devices_step4_title: "4. Перейти в офлайн",
    devices_step4_text: "Зачекайте, доки на головній сторінці з'явиться повідомлення, що PaperGames готовий до роботи офлайн, потім вимкніть Wi-Fi і перезавантажте сторінку. Зверніть увагу: сторінка і гра й далі відкриваються.",
    devices_step5_title: "5. Повернутися пізніше",
