    card_no_read: "Можна грати без читання",
    history_title: "Бібліотека історії ігор",
    history_intro: "Кожна гра в цій колекції має власну історію – деякі налічують понад п'ять тисяч років, інші — заледве десятиліття. Читайте їх тут, приблизно в порядку появи, або переходьте одразу до повної історії будь-якої гри.",
    history_dates_note: "Дати для найдавніших ігор є приблизними – їхнє точне походження часто губиться в історії або є предметом суперечок серед істориків.",
    history_read_more: "Повна історія →",
    home_history_title: "Цікаво, звідки взялися ці ігри?",
    home_history_desc: "Прочитайте історію походження кожної гри, від Стародавнього Єгипту до останнього десятиліття – жодного перегляду, лише історія.",
    home_chess_desc: "Класична гра. Локально удвох, проти вбудованого рушія або онлайн через Lichess.",
    home_go_desc: "Стародавня гра на територію. Локально удвох або проти вбудованого рушія, три розміри дошки, три рівні складності.",
    home_checkers_desc: "Класична гра зі стрибками та взяттям фігур. Локально удвох або проти вбудованого рушія, три рівні складності.",
    home_ur_desc: "Перегонова гра віком 4600 років, заново відкрита в стародавній Месопотамії. Локально удвох або проти вбудованого рушія, з клітинками-розетками та взяттям приземленням.",
    home_morris_desc: "Багатовікова стратегічна гра з розстановки та пересування фішок для утворення млинів. Локально удвох або проти вбудованого рушія, з класичним правилом «польоту» в ендшпілі.",
    home_backgammon_desc: "Класична гра в кістки на перегони. Локально удвох або проти вбудованого рушія, з баром, виведенням шашок і збиванням одиночних шашок.",
    home_xiangqi_desc: "Китайські шахи: генерали, слони, гармати та інші фігури на сітці 9x10. Локально удвох або проти вбудованого рушія, з перемиканням між класичними ієрогліфами та символами західного стилю.",
    home_mancala_desc: "Одна з найдавніших родин ігор світу: сійте зерна по дошці, щоб наповнити власну скарбницю. Локально удвох або проти вбудованого рушія, зі взяттями та додатковими ходами.",
    home_reversi_desc: "Змінюйте колір дошки, оточуючи фішки суперника. Локально удвох або проти вбудованого рушія.",
