    mahjong_shuffle: "Перетасувати фішки, що залишилися",
    chess_history_intro: "Від давньоіндійської воєнної гри до найбільш вивченої настільної гри у світі - шахи перетнули континенти й століття, щоб стати тим, чим вони є сьогодні.",
    go_history_intro: "Ґо - одна з найдавніших настільних ігор, що й досі грають у її первісному вигляді, - гра про територію та камені, чиє коріння, найімовірніше, сягає понад 2500 років у Китаї.",
    checkers_history_intro: "Шашки - гра простих правил і глибокої стратегії, що народилася з поєднання стародавньої дошки з новішим способом взяття фігур.",
    ur_history_intro: "Маючи приблизно 4600 років, Королівська гра Ур - одна з найдавніших знайдених настільних ігор, і завдяки детективній роботі, що тривала два тисячоліття, одна з небагатьох стародавніх ігор, у яку ми досі можемо грати за правилами, відтвореними зі стародавнього писемного джерела.",
    morris_history_intro: "Мало які ігри вирізьблювали на стількох різних поверхнях протягом стількох століть, як Млин, - від дахів єгипетських храмів до крит англійських соборів.",
    backgammon_history_intro: "Родовід нард проходить майже через кожну цивілізацію, що коли-небудь кидала кістки, - від стародавньої Месопотамії й Рима до кав'ярень сучасного Близького Сходу.",
    xiangqi_history_intro: "Китайські шахи мають глибоке спільне коріння з міжнародними шахами, проте пройшли власний окремий шлях довжиною понад тисячу років, щоб стати грою, у яку сьогодні грають сотні мільйонів людей.",
    mancala_history_intro: "Манкала - це не одна гра, а ціла родина ігор, одна з найдавніших ігрових родин на Землі, побудована навколо простої, універсальної дії - переміщення зерен чи каменів між лунками.",
    reversi_history_intro: "Вікторіанська салонна гра, що майже через століття повернулася в Японії під новою назвою і з фіксованою початковою позицією.",
    fourinarow_history_intro: "Проста ідея на силі тяжіння, що стала класикою в усьому світі.",
    gomoku_history_intro: "Проста гра на вишиковування в ряд, чия сама простота змусила змагальних гравців змінити її правила.",
    tictactoe_history_intro: "Мабуть, найвідоміша гра на папері – з коренями в Стародавньому Римі та місцем в історії комп'ютерів.",
    senet_history_intro: "Одна з найдавніших знайдених настільних ігор - і така, чиї точні правила загубилися на тисячі років.",
    shogi_history_intro: "Японська версія родини шахів, і єдиний великий варіант, де взята фігура не виходить із гри, - вона приєднується до сторони, що її взяла.",
    sudoku_history_intro: "На відміну від кожної іншої гри в цій добірці, судоку не має жодного стародавнього родоводу - у сучасному вигляді головоломка з'явилася лише 1979 року.",
    pegsolitaire_history_intro: "Головоломка для одного гравця, достатньо стара, щоб мати власну легенду про своє походження, і предмет одного з найдивовижніших результатів у розважальній математиці.",
    minesweeper_history_intro: "Головоломка, чиє визначальне правило - цілком безпечний перший хід - стало стандартом лише тоді, коли комп'ютери, а не друкована сторінка, змогли генерувати нову дошку на вимогу.",
    nonogram_history_intro: "Логічна головоломка, яку двічі незалежно винайшли в Японії приблизно в той самий час, - і названа на честь однієї з двох її авторів.",
    twenty48_history_intro: "Гра, побудована майже цілком з ідей інших ігор, створена за один вихідний і склонована більшою кількістю людей, ніж, мабуть, будь-яка браузерна гра до неї.",
    mahjong_history_intro: "Гра для одного гравця на підбір фішок, названа на честь і візуально запозичена з цілком іншої гри для чотирьох гравців, з якою вона має спільного мало що, окрім назви.",
    back_home: "← Назад на головну",
