    about_credits: "Шахові фігури («cburnett») Коліна М. Л. Бернетта, використано за ліцензією BSD (три пункти; повний текст у файлі NOTICE). Символьні фігури сянці: оригінальні малюнки Inductiveload, кожну фігуру доопрацював Kadagaden (github.com/Kadagaden/chess-pieces), за ліцензією CC BY-SA 4.0: https://creativecommons.org/licenses/by-sa/4.0/ Кандзі фігур сьогі: доопрацьовано з набору «kanji_light» від Kadagaden (github.com/Kadagaden/shogi-pieces), за ліцензією CC BY 4.0: https://creativecommons.org/licenses/by/4.0/ Значки «Сапера» і FreeCell на головній сторінці від Skoll і Aussiesim, з game-icons.net (CC BY 3.0).",
