    calm_point_1: "Без анімацій: ніщо не блимає, не ковзає й не стрибає. Кожна зміна з'являється одразу.",
    calm_point_2: "Без звуків.",
    calm_point_3: "Без реклами й сповіщень. Обліковий запис не потрібен – лише онлайн-шахи працюють через обліковий запис Lichess.",
