    calm_point_5: "Зроблено для рідерів з e-ink: темний текст на світлому тлі, а відмінності ніколи не позначено лише сірим чи кольором.",
    calm_point_6: "Без поспіху. Винятки: «Слова за категоріями» з необов'язковим часом раунду (типово вимкнено), годинник у «Сапері» і час на роздуми в онлайн-шахах на Lichess.",
    calm_point_7: "Після першого відкриття все працює без інтернету, якщо браузер це підтримує, – крім онлайн-шахів.",
    calm_point_8: "І для дітей: в іграх нічого не можна купити чи поширити. Сторінка «Про проєкт» містить добровільне посилання для пожертви через PayPal.",
