    msg_pairs_vehicle_submarine: "Підводний човен",
    pairs_history_intro: "Гра, якій узагалі не потрібна книжка з правилами: відкрий дві карти й запам'ятай, де що лежало.",
    msg_pairs_no_pair: "Не пара. Торкнися будь-де, щоб перевернути обидві карти назад.",
