    yatzy_history_intro: "Гра в кості, категорії підрахунку якої - пари, трійки й каре, фул-хаус, стріт - звучать як покерна комбінація, тому що саме звідти вони й походять.",

    game_bullsandcows: "Бики та корови",
    home_bullsandcows_desc: "Розгадайте прихований код із 4 фігур за обмежену кількість спроб за допомогою чорних і білих фішок-підказок. Повтори можуть бути дозволені залежно від рівня складності.",

