    bullsandcows_symbol_cross: "Хрест",


    bullsandcows_history_intro: "Суто логічна гра на розгадування коду без суперника, що почалася як гра на папері й стала улюбленою темою інформатиків, які вивчають, як найшвидше знайти прихований відповідь.",
    game_kakuro: "Какуро",
    home_kakuro_desc: "Заповніть білі клітинки цифрами від 1 до 9 так, щоб кожен ряд у сумі дорівнював своїй підказці, без повторення цифри в межах одного ряду. Генерується щоразу заново, у трьох рівнях складності.",

