    game_blockers: "Перекритий шлях",
    home_blockers_desc: "Перегони з кубиком до мети вгорі поля для 2–6 гравців: блоки перекривають доріжки, а хто стане на блок, ставить його на шляху інших. Проти комп'ютера або з друзями на одному пристрої.",
    bl_level_label: "Рівень",
    bl_board_aria: "Поле «Перекритий шлях»",
    bl_history_intro: "«Перекритий шлях» — гра-перегони PaperGames; вона використовує давні елементи ігор-перегонів з кубиком, як-от відправлення фішок додому та перекриття шляху.",
    quickrules_blockers_1: "Киньте кубик і пересуньте одну фішку рівно на стільки клітинок доріжками до мети вгорі.",
    quickrules_blockers_2: "Жодна фішка не може пройти через блок. Ставши на блок, ви ставите його на іншу вільну клітинку — на шляху в когось іншого. Перед грою виберіть: мало, звичайно чи багато блоків.",
    quickrules_blockers_3: "У верхній половині (круглі клітинки) ставши на фішку іншого гравця, ви відправляєте її додому; на квадратних клітинках нижче фішки в безпеці. Перемагає перша фішка в меті або, якщо так обрано перед грою, гравець, який першим має всі фішки в меті.",
    quickrules_blockers_4: "Дошка «Швидка» (вибирається перед грою): менша, по 4 фішки; на клітинці відпочинку (восьмикутник) фішка в безпеці, там уміщується лише одна фішка і не можна ставити блок.",
