    home_poker_desc: "Техаський холдем проти 1–3 комп'ютерів: дві свої карти, п'ять спільних і фіксовані ставки — скинути, зрівняти або підвищити. Перемагає найкраща комбінація з п'яти карт. Гра йде на фішки — це лише очки в грі.",
