    game_schafkopf: "Schafkopf",
    home_schafkopf_desc: "Баварська карткова гра на чотирьох із німецькими картами: ви проти трьох комп'ютерів у заушпіль, венц і соло, зі шнайдером, шварцом, лауфенде й записом очок. Лише очки.",
    sf_history_intro: "Шафкопф уперше згадано 1782 року в Саксонії; першу явно баварську гру засвідчено 1849 року.",
    quickrules_schafkopf_1: "Пасуйте або оголосіть гру: заушпіль (ви викликаєте туза, його власник — ваш партнер), венц або соло.",
    quickrules_schafkopf_2: "Обери й унтери — старші козирі (у Венці лише унтери); ходіть у масть. Викликаний туз мусить вийти, коли ходять у його масть.",
    quickrules_schafkopf_3: "Стороні гравця потрібно 61 зі 120 очок. Шнайдер, шварц і лауфенде підвищують виграш.",
