    game_canasta: "Canasta",
    home_canasta_desc: "Класична гра типу ремі для двох, 108 карт: комбінації з карт одного значення, канасти із семи карт, джокери й двійки як дикі карти, червоні й чорні трійки. Ти проти комп'ютера, до 5000 очок або коротка гра до 2000.",
    cn_history_intro: "Канаста походить із Монтевідео (Уругвай); зазвичай її датують 1939 роком, хоча деякі джерела називають пізніший рік. 1949 року вона потрапила до Нью-Йорка.",
    quickrules_canasta_1: "Візьми дві карти з колоди або весь скид – його верхня карта мусить одразу піти в комбінацію.",
    quickrules_canasta_2: "Викладай щонайменше три карти одного значення; джокери й двійки дикі. Сім карт утворюють канасту.",
    quickrules_canasta_3: "Маючи дві канасти, можна вийти. Червоні трійки дають бонус; гра йде до 5000 очок (коротка: 2000).",
