    game_bridge: "Bridge",
    home_bridge_desc: "Контрактний бридж учотирьох: ти і твій партнер-комп'ютер проти двох комп'ютерів. Торгівля з кнопками, болван відкритий на столі, підрахунок «Чикаго» (чотири роздачі) або робер.",
    br_history_intro: "Бридж походить від віста; перші відомі правила («Biritch, or Russian Whist») датуються 1886 роком, контрактний бридж — 1925.",
    quickrules_bridge_1: "Заяви, скільки взяток понад шість візьме твоя сторона, з козирною мастю або без козиря; найвища заявка стає контрактом.",
    quickrules_bridge_2: "Розігрувач грає обома руками: болван (його партнер) лежить відкрито. Ходи в масть; старший козир виграє.",
    quickrules_bridge_3: "Виконай контракт, щоб отримати очки; якщо взяток забракне, очки отримають суперники. «Чикаго»: чотири роздачі.",
