    game_tenpairs: "Пари до десяти",
    home_tenpairs_desc: "Головоломка на папері: викреслюєш пари цифр, рівні або такі, що разом дають 10, якщо вони «бачать» одна одну. Ходів немає — дописуєш решту цифр. Класичний або випадковий старт, три рівні.",
    tp_history_intro: "Головоломка зі шкільних зошитів; її походження не задокументоване.",
    quickrules_tenpairs_1: "Торкнися двох цифр, які рівні (3 і 3) або разом дають 10 (3 і 7), щоб викреслити їх.",
    quickrules_tenpairs_2: "Вони мають бачити одна одну: стояти поруч по горизонталі, вертикалі чи діагоналі або лише з викресленими клітинками між ними; по горизонталі — і через кінець рядка.",
    quickrules_tenpairs_3: "Ходів немає? Натисни «Дописати»: решту цифр записують ще раз у кінці (не більше 5 разів). Викресли всі цифри, щоб перемогти.",
