    home_mathcross_desc: "Розставте числа від 1 до 9, кожне один раз, щоб кожен рядок і кожен стовпець сходилися - рахуємо зліва направо. Три рівні, завжди рівно один розв'язок, без вгадування.",
    mc_history_intro: "Числова головоломка з обчислень у рядках і стовпцях, споріднена з давнім магічним квадратом із чисел від 1 до 9.",
    quickrules_mathcross_1: "Впишіть числа від 1 до 9 у клітинки, кожне рівно один раз.",
    quickrules_mathcross_2: "Кожен рядок і кожен стовпець мусить давати свій результат. Рахуємо зліва направо (згори вниз), без пріоритету множення: 3 + 4 × 2 = 14.",
    quickrules_mathcross_3: "Торкніться клітинки, а потім числа. Позначка або хрестик показує, чи сходиться заповнений рядок або стовпець.",
    game_cardduel: "Карткова дуель",
    home_cardduel_desc: "Фентезійна карткова гра для двох магів: істоти й чари, чотири готові колоди лісу, вогню, води та каменю. Проти комп’ютера на трьох рівнях або удвох на одному пристрої.",
    quickrules_cardduel_1: "Зведи життя ворожого мага до 0.",
    quickrules_cardduel_2: "На початку кожного ходу додається 3 сили; невикористана сила залишається (до 9). Торкнися карти, потім «Зіграти»: істоти лишаються на столі, чари діють один раз.",
    quickrules_cardduel_3: "Щоб атакувати, торкнися готової істоти (товста рамка), потім цілі; нові істоти атакують одразу. Месник першим б’є істот, які атакують його мага.",
