    home_villains_desc: "Кожен грає лиходієм із казок братів Грімм із власною метою – відьмою, вовком, Румпельштільцхеном та іншими, – а решта ставить йому на шляху героїв. Від 2 до 4 гравців, проти комп’ютера або на одному пристрої.",
