    home_forestvillage_desc: "Лісові звірі збирають глину, насіння й пір’я, розміщують працівників і будують власне селище. Відповідний звір зменшує вартість будівлі на одне пір’я. 1–4 гравці, наодинці або проти комп’ютера.",
    quickrules_forestvillage_1: "Набери найбільше очок за карти, пари й завдання. Гра завершується, коли всі закінчать зиму.",
