    ab_room_cave_10: "Одну стіну вкривають дивні малюнки зірок.",
    ab_room_cave_11: "Сталактити звисають зі стелі, наче кам’яні бурульки.",
    ab_room_cave_12: "Маленька бічна печера. Хтось залишив тут старий коц.",
    ab_room_cave_13: "Стежка піднімається гладкими каменями, слизькими від моху.",
    ab_room_cave_14: "У темному кутку сплять кажани. Ти йдеш навшпиньки.",
    ab_room_cave_15: "Кругла кімната з гладкою, ніби відполірованою підлогою.",
    ab_room_cave_16: "Зелений мох освітлює стіни блідим сяйвом.",
    ab_room_cave_17: "Колись тут був мотузяний міст. Лишилися тільки стовпці.",
    ab_room_cave_18: "Тут тепле повітря. Десь глибоко внизу щось гуркоче.",
    ab_room_cave_19: "Усюди лежать уламки кристалів, ніби тріснув великий камінь.",
    ab_room_cave_20: "Тихий закуток. Твоя лампа кидає довгі тіні.",
    ab_room_tower_1: "Полиці, повні запорошених книжок, сягають стелі.",
    ab_room_tower_2: "Гвинтові сходи в’ються вгору. Сходинки рипять.",
    ab_room_tower_3: "Круки сидять на сволоку й дивляться на тебе блискучими очима.",
    ab_room_tower_4: "Стара кухня. Над холодним вогнищем висить казан.",
    ab_room_tower_5: "Крізь кругле вікно ти бачиш ліс далеко внизу.",
    ab_room_tower_6: "Кабінет із величезним столом. Чорнило в каламарях висохло.",
    ab_room_tower_7: "За скляною стіною повільно обертаються шестерні. Тік-так.",
    ab_room_tower_8: "Довгий коридор із портретами. Їхні очі ніби стежать за тобою.",
    ab_room_tower_9: "Кімната, повна мап. Одна з них показує таку саму вежу.",
    ab_room_tower_10: "На столі горять свічки, хоча тут, здається, нікого немає.",
    ab_room_tower_11: "Комора з банками сушених трав і різнобарвних порошків.",
    ab_room_tower_12: "Вітер свистить крізь зламану віконницю.",
    ab_room_tower_13: "Музична кімната. Арфа сама собою грає ноту.",
    ab_room_tower_14: "Вузький місток із дощок веде від однієї стіни до іншої.",
    ab_room_tower_15: "Спальня з ліжком під балдахіном. Завіси всі в дірках.",
    ab_room_tower_16: "Майстерня з підзорною трубою, спрямованою в небо.",
    ab_room_tower_17: "Чорне пір’я лежить по всій підлозі.",
    ab_room_tower_18: "На стіні висить дзеркало, але в ньому видно іншу кімнату.",
    ab_room_tower_19: "Маленький балкон. Тут, нагорі, вітер пахне дощем.",
    ab_room_tower_20: "Прохолодна зала з підлогою з чорних і білих плиток.",
    ab_room_forest_1: "Між деревами висить туман. Ледве видно власну руку.",
    ab_room_forest_2: "Галявина, повна квітів. Бджоли гудуть на сонці.",
    ab_room_forest_3: "Стара стежка, заросла папороттю.",
    ab_room_forest_4: "Дупласте дерево, таке велике, що в ньому можна стояти.",
    ab_room_forest_5: "Маленький ставок. Жаби стрибають у воду, коли ти підходиш.",
    ab_room_forest_6: "Коріння завтовшки з руку перетинає стежку.",
    ab_room_forest_7: "Високо в кронах дерев співають птахи.",
    ab_room_forest_8: "У траві лежить коло з білих каменів.",
    ab_room_forest_9: "Уздовж кам’яного муру ростуть ожинові кущі.",
    ab_room_forest_10: "Земля м’яка й зелена від моху. Дуже тихо.",
    ab_room_forest_11: "Повалений стовбур лежить над яром, наче міст.",
    ab_room_forest_12: "Покинута хатина. Двері відчинені.",
    ab_room_forest_13: "Високі сосни рипять на вітрі.",
    ab_room_forest_14: "Маленькі вогники танцюють над болотом.",
    ab_room_forest_15: "Величезний дуб із вирізаним у корі обличчям.",
    ab_room_forest_16: "Гриби ростуть у рівному колі.",
    ab_room_forest_17: "Струмок дзюрчить по гладеньких камінцях.",
    ab_room_forest_18: "Темні хащі. Гілки дряпають рукави.",
    ab_room_forest_19: "Сонячний пагорб. Звідси туман унизу схожий на море.",
    ab_room_forest_20: "Старі кам’яні сходинки ведуть між двома березами.",
    home_adventurebook_desc: "Рольова гра для однієї людини: створи героя, досліджуй кімнату за кімнатою печеру, вежу або ліс, кидай кубики в пробах і боях і принеси загублений скарб. Легкий, Середній або Складний.",
