    game_differences: "Знайди відмінності",
    home_differences_desc: "Дві картинки, що відрізняються в 3, 5 або 7 місцях: чогось бракує, інший візерунок, віддзеркалено чи зсунуто. Торкніться відмінності на будь-якій із двох картинок. Без поспіху, з підказкою, якщо застрягли. Або «Знайди на малюнку»: знайдіть від 5 до 10 речей на великому малюнку кімнати - кухні, горища, саду та ще дев'яти.",
    df_history_intro: "Головоломка, відома з газет, дитячих журналів і збірок головоломок; коли й де вона з'явилася вперше, достовірно не задокументовано.",
