    msg_df_search_hint: "Підказка: одна з речей у позначеному місці.",
    game_pentomino: "Пентаміно",
    home_pentomino_desc: "Складіть дванадцять фігур із п'яти квадратів у прямокутник - повертайте й віддзеркалюйте дотиком, без перетягування. Вільне складання в чотирьох розмірах або із заданими стартовими фігурами й рівно одним розв'язком.",
    pt_history_intro: "Дванадцять фігур із п'яти квадратів кожна: головоломку опублікував Генрі Дьюдені 1907 року, а назву «пентаміно» дав Соломон Голомб 1953 року.",
    quickrules_pentomino_1: "Заповніть прямокутник фігурами; кожну клітинку буде вкрито рівно один раз.",
    quickrules_pentomino_2: "Виберіть фігуру під полем, поверніть або віддзеркальте її, а потім торкніться клітинки, куди має лягти її крапка. Торкніться викладеної фігури, щоб знову її взяти.",
    quickrules_pentomino_3: "У режимі «Задані стартові фігури» деякі фігури лежать нерухомо, а решта пасують лише одним способом.",
