    msg_pt_choose: "Виберіть фігуру під полем.",
    msg_pt_place: "За потреби поверніть або віддзеркальте її, а потім торкніться місця, куди має лягти її крапка.",
    msg_pt_nofit: "Фігура туди не вміщається.",
