    msg_t_pt_picked: "Фігуру {s} взято.",
    msg_pt_won: "Прямокутник заповнено - розв'язано!",
    msg_t_pt_hint_place: "Підказка: фігура {s} лягає в позначене місце.",
    msg_t_pt_hint_remove: "Підказка: фігура {s} заважає розв'язку - заберіть її.",
    msg_pt_hint_none: "Підказка: шляху не знайдено - заберіть якусь фігуру.",
    msg_t_pt_info: "Викладено: {n} з {m} фігур",
    game_arrows: "Стрілки",
    home_arrows_desc: "Торкніться стрілки, і вона вислизне з поля - якщо їй не заважає інша стрілка. Очистіть усе поле; кожна головоломка має розв'язок, є скасування, підказки й жодного обмеження часу. На рівнях «Складний» і «Майстер» заблоковані стрілки ковзають уперед і можуть застрягнути.",
    aw_history_intro: "Деталі, що можуть ковзати лише в один бік, - родичі пересувних головоломок, які 1880 року стали справжнім захопленням; варіант зі стрілками - молода головоломка.",
    quickrules_arrows_1: "Торкніться стрілки: вона залишає поле у своєму напрямку, якщо шлях до краю вільний.",
    quickrules_arrows_2: "Якщо на шляху інша стрілка, нічого не відбувається - спершу приберіть ту. На рівнях «Складний» і «Майстер» вона натомість ковзає до тієї стрілки.",
    quickrules_arrows_3: "Очистіть усе поле. Кожна головоломка має розв'язок; «Підказка» позначає стрілку, яка може вийти.",
    aw_win_title: "Поле очищено!",
    aw_aria_cell: "Рядок {R}, стовпець {C}",
    aw_aria_empty: "порожньо",
    aw_aria_arrow: "стрілка {D}",
    aw_dir_0: "вгору",
    aw_dir_1: "праворуч",
    aw_dir_2: "вниз",
    aw_dir_3: "ліворуч",
    msg_aw_start: "Торкніться стрілки, щоб відправити її з поля.",
    tg_level_outline: "Лише контур",
    game_loosen: "Розчепи кільця",
    home_loosen_desc: "Зчеплені між собою кільця, кожне з розривом: обертай їх - зчеплені кільця обертаються у протилежний бік - доки вони не звільняться одне за одним. Три рівні, з найменшою кількістю ходів, скасуванням і підказками.",
    lr_history_intro: "Головоломки з кільцями давні - китайські кільця описували ще близько 1500 року; ця плоска версія з розривами нова.",
    quickrules_loosen_1: "Торкнися кільця: воно повертається на чверть оберту за годинниковою стрілкою, а зчеплені з ним - у протилежний бік.",
    quickrules_loosen_2: "Кільце вільне, коли його розрив там, де зчеплене кільце лежить зверху - торкнися його, і воно вийде.",
    quickrules_loosen_3: "Вийми всі кільця; спершу ті, що на кінцях. «Підказка» показує хід.",
    lr_win_title: "Усі вільні!",
