    dg_dice_none: "Ще не кинуто",
    dg_roll: "Кинути",
    game_weidefreunde: "Друзі з пасовища",
    home_weidefreunde_desc: "Карткова гра з кубиком для дітей: кидай кубик із тваринами й збирай на своєму пасовиську п'ять тварин із ферми – корову, вівцю, свиню, курку й коня. Лише малюнки, читати не треба, без обмеження часу. Проти комп'ютера або до чотирьох гравців на одному пристрої.",
    weidefreunde_history_intro: "Ігри з малюнками замість цифр і з картками для збирання – одні з перших ігор для малюків; ця поєднує і те, і те.",
    quickrules_weidefreunde_1: "Кинь кубик. Він показує тварину або фермера.",
    quickrules_weidefreunde_2: "Якщо на подвір'ї лежить картка цієї тварини, а на твоєму пасовиську її немає, картка йде до тебе. З фермером береш будь-яку картку, якої тобі бракує. Інакше поверни одну картку з подвір'я.",
    quickrules_weidefreunde_3: "Перемагає той, хто першим матиме на пасовиську всіх п'ять тварин.",
    wf_animal_0: "корова",
