    wf_slot_free_aria: "{animal}, ще бракує",
    wf_die_aria: "Кубик: {face}",
    wf_count: "{n} з {m}",
    wf_full_pasture: "Одне пасовисько заповнене: там усі п'ять тварин.",
    wf_howto_title: "Як це працює",
    wf_howto_1: "Кинь кубик. Він показує тварину або фермера.",
    wf_howto_2: "Картка цієї тварини переходить із двору на твоє пасовисько, якщо цієї тварини в тебе ще немає.",
    wf_howto_3: "Фермер: візьми будь-яку картку двору, якої тобі бракує. Немає картки для тебе: відішли одну картку двору назад.",
    wf_howto_4: "Мета: усі п'ять тварин на твоєму пасовиську. Хто першим їх має, той виграє.",
    wf_howto_show: "Як це працює?",
    wf_howto_hide: "Сховати пояснення",
    howto_title: "Як це працює",
    howto_show: "Як це працює?",
    howto_hide: "Сховати пояснення",
    game_zoowurf: "Кидок у зоопарку",
    home_zoowurf_desc: "Гра в кубики для дітей: кидай кубики зі тваринами й заповни картку тваринами, які на ній намальовані – левом, слоном, жирафою, мавпою та пінгвіном. Лише малюнки, читати не треба, без обмеження часу. Проти комп'ютера або до чотирьох гравців на одному пристрої.",
    zoowurf_history_intro: "Кидання кубиків і добір малюнків – одні з перших ігор малят; ця гра поєднує обидва, на прикладі тварин із зоопарку.",
    quickrules_zoowurf_1: "У кожного є власна картка. На ній зображені тварини, які тобі треба викинути.",
    quickrules_zoowurf_2: "Кидай один раз за хід. Кубики з твариною з твоєї картки або з лапою залишаються на картці.",
    quickrules_zoowurf_3: "Заповнена картка дає одне очко за кожну тварину; потім візьми відкриту картку. Коли хтось набере 12 очок, раунд дограють до кінця. Перемагає той, у кого найбільше очок.",
    game_pfotenwurf: "Кидок лапкою",
    home_pfotenwurf_desc: "Гра в кубики для дітей із кубиками-звірятами: кидай до трьох разів, залишай потрібних звірів і заповнюй свій аркуш – леви, слони, два чи більше однакових, усі різні. Лапа – це джокер. Лише малюнки, без лічби. Самому, проти комп’ютера або до чотирьох гравців на одному пристрої.",
    pfotenwurf_history_intro: "Кинути п’ять кубиків до трьох разів і вибрати, куди записати очки, – давня ідея ігор у кубики, тут зі звірами замість чисел.",
    quickrules_pfotenwurf_1: "Кинь п’ять кубиків зі звірами. Торкнися кубиків, які хочеш залишити, і перекинь інші – до трьох разів.",
    quickrules_pfotenwurf_2: "Потім торкнися вільного поля на своєму аркуші. Лапа рахується як будь-який звір. Поле, яке не підходить, отримує 0 очок.",
    quickrules_pfotenwurf_3: "Коли всі поля заповнені, гра закінчується. Перемагає той, хто має найбільше очок.",
    ty_mode_people: "Люди на одному пристрої",
    ty_goal_line: "Мета: заповни всі поля свого аркуша. Перемагає той, хто має найбільше очок.",
    ty_dice_label: "Кубики",
    ty_roll: "Кинути кубики",
