    game_nim: "Нім",
    home_nim_desc: "По черзі беріть камінці з купок – хто візьме останній, той виграє (або в мізері програє). Проти комп’ютера на трьох рівнях або вдвох.",
    nim_history_intro: "Гра в забирання камінців, якій Чарлз Л. Бутон дав назву й розв’язок 1901 року.",
    quickrules_nim_1: "У свій хід візьми один чи кілька камінців з одного ряду: торкнися камінця, до якого хочеш брати, потім «Взяти камінці».",
