    zw_count: "{n} з {m}",
    zw_goal_line: "Мета: кожна тварина на заповненій картці дає одне очко. Коли хтось набере 12 очок, раунд дограють до кінця. Перемагає той, у кого найбільше очок.",
    zw_level_label: "Комп’ютер:",
    zw_level_normal: "Звичайний",
    zw_level_beginner: "Новачок",
    zw_howto_1: "У кожного є власна картка. На ній зображені потрібні тобі тварини.",
    zw_howto_2: "Кидай один раз за хід. Кубики з твариною з твоєї картки залишаються на ній.",
    zw_howto_3: "Ти сам кладеш лапу на будь-яку вільну тварину.",
    zw_howto_4: "Заповнена картка дає одне очко за кожну тварину. Потім візьми одну з двох відкритих карток. Після ходів комп’ютера натисни Далі.",
    game_klappenkasten: "Klappenkasten",
    home_klappenkasten_desc: "Традиційна гра в кубики: кинь два кубики й закрий пронумеровані клапани, що разом дають твій кидок. Коли нічого не підходить, відкриті клапани рахуються проти тебе – перемагає той, у кого найменше балів, а закрити всі клапани означає виграти одразу. Проти комп'ютера або до чотирьох гравців на одному пристрої.",
    kk_history_intro: "Традиційна гра в кубики з рядом пронумерованих клапанів, у яку грали в шинках і на кораблях – де й коли саме вона виникла, достеменно невідомо.",
    quickrules_klappenkasten_1: "Кинь два кубики й закрий клапани, номери яких разом дають кидок – один або кілька.",
    quickrules_klappenkasten_2: "Кидай і закривай далі. Коли нічого не підходить, номери відкритих клапанів – твої бали.",
    quickrules_klappenkasten_3: "Перемагає той, у кого найменше балів; закрити всі клапани – виграти одразу. «Скасувати» відміняє закриття.",
    kk_goal_line: "Мета: закривай клапани, сума яких дорівнює твоєму кидку. Мало відкритих клапанів – мало очок; виграє той, хто має найменше очок.",
    kk_howto_1: "Кинь обидва кубики.",
    kk_howto_2: "Закрий стулки, які разом дають суму: 8 — це 3 і 5.",
    kk_howto_3: "Кинь ще раз і закривай інші стулки, поки якісь підходять.",
    kk_howto_4: "Коли нічого не підходить, твій хід закінчується. Відкриті стулки — це твої очки: перемагає той, у кого їх менше.",
