    sw_again_hint: "Подвійна шістка! Кинь ще раз.",
    game_steckwuerfeln: "Steckwürfeln",
    home_steckwuerfeln_desc: "Традиційна гра з кубиками й кілочками, одинадцять отворів з номерами від 2 до 12: кинь два кубики й встав кілочок в отвір із сумою або у два отвори окремих кубиків. Кидай далі, поки щось підходить – вільні отвори рахуються проти тебе, перемагає той, у кого найменше балів. Варіанти: подвійна шістка як джокер або спільна дошка, де вибуває той, хто не може вставити кілочок.",
    sw_history_intro: "Невелика традиційна гра в кубики на дошці з пронумерованими отворами й кілочками – проста, давня й досі доступна як дерев'яна кишенькова гра.",
    quickrules_steckwuerfeln_1: "Кинь два кубики. Встав кілочок в отвір із сумою або у два отвори окремих кубиків (2 і 4: отвір 6 або отвори 2 і 4).",
    quickrules_steckwuerfeln_2: "Кидай і вставляй далі. Коли нічого не підходить, номери вільних отворів – твої бали.",
    quickrules_steckwuerfeln_3: "Перемагає той, у кого найменше балів. Подвійна шістка – джокер (кинь ще раз). «Скасувати» забирає кілочок назад.",
    sw_goal_line: "Мета: встромляй кілочки в отвори. Вільні отвори рахуються як очки; виграє той, хто має найменше очок.",
