    sw_shared_message: "Інші більше не могли вставити кілочок.",
    game_sternjagd: "Sternjagd",
    home_sternjagd_desc: "Гра в наздоганяння для двох-чотирьох гравців з одним кубиком: випале число — це точна кількість кроків уздовж стрілок на зіркоподібній дошці. Хто зупиниться на супернику, забирає в нього одну з трьох зірок; проходження повз нічого не змінює. Перемагає останній, у кого ще лишилися зірки.",
    sj_history_intro: "Ігри в наздоганяння з кубиком відомі в багатьох культурах; ця версія має власну дошку зі стрілками.",
    quickrules_sternjagd_1: "Кинь кубик і пройди рівно стільки кроків уздовж стрілок. Торкнись одного з позначених полів.",
    quickrules_sternjagd_2: "Закінчи хід на супернику, щоб упіймати його: він втрачає зірку й повертається в кут. Проходження повз нічого не змінює.",
    quickrules_sternjagd_3: "У кожного три зірки. Перемагає останній, у кого лишилися зірки. «Скасувати» повертає хід.",
    quickrules_sternjagd_4: "Удвох другий гравець першого разу ходить двічі поспіль (можна вимкнути).",
    sj_roll: "Кинути кубик",
