    sj_starts: "Починає: {name}.",
    sj_starts_you: "Ти починаєш.",
    sj_balance_label: "Вирівнювання для другого гравця",
    sj_balance_note: "Першого разу {name} ходить двічі поспіль.",
    sj_balance_note_you: "Першого разу ти ходиш двічі поспіль.",
    sj_last_again: "Ще один хід (вирівнювання).",
    game_teufelsieben: "Чортова сімка",
    home_teufelsieben_desc: "Карткова гра на ризик: відкривайте карти по одній і вчасно зупиніться. Повтор числа означає програш; ряд із чотирьох чи більше чисел дає бонус. Для 2–6 гравців, проти комп’ютера або на одному пристрої.",
    quickrules_teufelsieben_1: "У свій хід відкривайте карти по одній. Після першої можна зупинитися будь-коли.",
    quickrules_teufelsieben_2: "Повтор числа означає програш: нуль очок за раунд. Раунд завершується, коли всі зробили хід.",
    quickrules_teufelsieben_3: "Ряд із чотирьох чи більше чисел дає бонус. Особливі карти змінюють карти або очки.",
    ts_history_intro: "Продовжити чи зупинитися? Чортова сімка — карткова гра на ризик для PaperGames.",
