    game_gipfelwurf: "Кидок до вершини",
    home_gipfelwurf_desc: "Ризикована гра в кості: кинь три кості; дві визначають хребет, третя — кроки. Продовжуй підйом або розбий табір; якщо кидок не підходить до твого хребта, підйом цього ходу пропадає. Хатини захищають, а тріщини відкидають назад. Для 2–4 гравців, проти комп’ютера або на одному пристрої.",
    quickrules_gipfelwurf_1: "Кинь три кості: сума двох визначає хребет, а третя — кількість кроків (1–2: один, 3–4: два, 5–6: три). За хід ти підіймаєшся лише одним хребтом.",
    quickrules_gipfelwurf_2: "Кидай знову або розбий табір. Якщо кидок не підходить до твого хребта, підйом цього ходу пропадає, якщо тільки ти не дістався хатини. Якщо точно потрапиш на тріщину, відступи на два кроки.",
    quickrules_gipfelwurf_3: "Кожен крок у твоїх таборах дає одне очко; той, хто першим досяг вершини, отримує ще 6, наступні — по 3. Коли хтось досягне цілі, дограйте раунд. Перемагає гравець із найбільшою кількістю очок.",
    gw_history_intro: "Кидати далі чи розбити табір? «Кидок до вершини» – гра в кубики з ризиком, створена для PaperGames, зі старої родини ігор у кубики, де ще один кидок може коштувати всього.",
