    gw_howto_4: "Хатина захищає, тріщина відкидає назад.",
    game_advent: "Адвент-календар головоломок",
    home_advent_desc: "24 віконця, за кожним — невелика головоломка: Вимикач, міні-судоку, нонограма, Futoshiki, Хмарочоси та Calcudoku. Віконце відчиняється у відповідний день грудня, коли розв’язано попереднє.",
    quickrules_advent_1: "З 1 до 24 грудня щодня відчиняється одне віконце. За ним — невелика головоломка на кілька хвилин.",
    quickrules_advent_2: "Віконце відчиняється, лише коли розв’язано попереднє. Пропустив день? Розв’яжи попередні віконця — і наступні відчиняться.",
    quickrules_advent_3: "Торкнися клітинки, а потім числа внизу. У нонограмі клітинка стає зафарбованою, потім закресленою, а тоді знову порожньою.",
    adv_history_intro: "Відлік днів до Різдва: від крейдяних рисок на дверях до друкованих календарів із маленькими віконцями, а тут — одна невелика головоломка щодня.",
