    adv_kind_calcudoku: "Calcudoku",
    adv_how_lights: "Вимкни всі лампи. Дотик перемикає вибрану лампу та сусідні: зверху, знизу, ліворуч і праворуч.",
    adv_how_sudoku: "У кожному рядку, стовпці та блоці кожне число має бути один раз.",
    adv_how_nonogram: "Числа послідовно показують групи зафарбованих клітинок у кожному рядку та стовпці.",
    adv_how_futoshiki: "У кожному рядку та стовпці кожне число має бути один раз. Знаки вказують на менше число.",
    adv_how_skyscrapers: "У кожному рядку та стовпці кожне число має бути один раз; число позначає висоту вежі. Підказка показує, скільки веж видно звідти.",
    adv_how_calcudoku: "У кожному рядку та стовпці кожне число має бути один раз. Числа в блоці з указаним знаком дають його значення.",
    adv_not_yet: "Усі клітинки заповнені, але щось іще не сходиться.",
