    adv_state_off: "вимкнена",
    adv_text_1: "Перше віконце відчинено — попереду ще 23.",
    adv_text_2: "Надворі рано темніє; головоломка пасує до довгих вечорів.",
    adv_text_3: "Чашка чаю й малюнок із квадратиків — гарний початок дня.",
    adv_text_4: "Дні спливають один за одним.",
    adv_text_5: "Надворі, можливо, буде перший мороз; тут числа стають на місце.",
    adv_text_6: "Майже тиждень грудня вже позаду.",
    adv_text_7: "Тиждень головоломок позаду — чудово впорався!",
    adv_text_8: "Списки, листи, невеликі плани: грудень насичений, і це віконце вже готове.",
    adv_text_9: "Десь саме зараз падають перші сніжинки.",
    adv_text_10: "Десять віконець відчинено — календар заповнюється.",
    adv_text_11: "Короткі дні, довгі ночі: гарна пора подумати.",
    adv_text_12: "Ти майже пройшов половину календаря.",
    adv_text_13: "Теплий напій, тиха хвилина, розв’язана головоломка.",
    adv_text_14: "Два тижні грудня — відлік у самому розпалі.",
    adv_text_15: "Десь печуть печиво, а тут розв’язують головоломку.",
    adv_text_16: "Залишилося лише вісім віконець.",
    adv_text_17: "Світлі вікна на темній вулиці — і ще одне віконце відчинене.",
    adv_text_18: "Пакувальний папір, стрічки й ще одна розв’язана головоломка.",
    adv_text_19: "Рік майже закінчився; головоломки допомагають триматися.",
    adv_text_20: "Двадцять віконець — залишилося лише чотири.",
    adv_text_21: "Залишилося лише три віконця — календар майже повний.",
    adv_text_22: "Майже готово: ще кілька віконець — і календар буде повний.",
    adv_text_23: "День перед останнім віконцем — молодець, що дійшов так далеко.",
    adv_text_24: "Усі 24 віконця відчинені. Гарних свят і спокійного часу!",
    sj_last_capture: "{name}: випало {n}, спіймано гравця {victim}: на одну зірку менше.",
