    game_kleeberg: "Kleeberg",
    home_kleeberg_desc: "Гра-будівництво для двох на піраміді з круглих полів: по черзі кладіть серця або конюшини на вільні поля, але тільки на два заповнені поля. Три власні знаки на прямій лінії виграють.",
    kb_history_intro: "Kleeberg — нова гра з власними правилами; вона спирається на давню ідею «три в ряд».",
    quickrules_kleeberg_1: "По черзі: поклади серце або конюшину на поле з кільцем.",
    quickrules_kleeberg_2: "Будуй угору: поле відкрите, лише якщо обидва поля під ним заповнені.",
    quickrules_kleeberg_3: "Три власні знаки на прямій лінії виграють. Якщо піраміда заповнена і ні в кого немає лінії, це нічия.",
