    kb_field_locked: "ще не відкрите",
    kb_over_message: "Три на прямій лінії виграють. Повна піраміда без лінії — це нічия.",
    kq_cards_label: "Картки",
    game_oddone: "Що тут зайве?",
    home_oddone_desc: "Кілька карток схожі в одному, крім однієї: торкнись тієї, що не підходить. Малюнки з однієї групи або фігури, що збігаються за однією ознакою. Шість раундів у грі, три рівні, великі кнопки, без обмеження часу, а коли застрягнеш – підказка.",
    oddone_history_intro: "Знайти зайве – класична вправа зі шкільних підручників і тестів на мислення: вона вчить впорядковувати речі за їхніми ознаками.",
    quickrules_oddone_1: "Кілька карток схожі в одному, крім однієї.",
    quickrules_oddone_2: "Торкнись картки, яка не підходить. Хибну буде закреслено – спробуй іншу.",
    quickrules_oddone_3: "Шість раундів – це одна гра. Часу не обмежено, а підказка позначає картку, що не підходить.",
    od_win_title: "Усі раунди готові!",
    msg_od_start: "Яка картка зайва? Торкнись її.",
