    msg_od_hint: "Підказка: позначена картка – зайва.",
    msg_t_od_won: "Усі раунди готові! Помилок: {n}.",
    msg_t_od_won_modal: "Усі раунди готові. Помилок: {n}.",
    msg_t_od_info: "Раунд {n} з {m} · Помилок: {k}",
    msg_t_od_aria_option: "Картка {n}",
    msg_t_od_aria_wrong: "Картка {n}, неправильна",
    msg_t_od_aria_right: "Картка {n}, правильна",
    kq_shadows_label: "Тіні",
    family_picturelogic: "Логічні картинки",
    game_shadowmatch: "Чия це тінь?",
    home_shadowmatch_desc: "Малюнок і кілька чорних тіней: яка з них йому належить? Шість малюнків у грі, три рівні – на складному той самий малюнок трапляється ще й повернутим або віддзеркаленим. Великі кнопки, без обмеження часу, а коли застрягнеш – підказка.",
    shadowmatch_history_intro: "Тіні століттями обводили, вирізали й використовували для гри – добирати тінь до предмета означає трохи потренувати уважність.",
