    game_catplaces: "Місця для котів",
    home_catplaces_desc: "У кожному рядку, кожному стовпці й кожній кімнаті має бути рівно один кіт - і два коти не можуть торкатися, навіть кутом. Логічні головоломки трьох розмірів, кожна з одним розв'язком, розв'язуються без вгадування.",
    kz_history_intro: "Правила походять від логічної головоломки, вигаданої 2003 року для чемпіонату світу з головоломок у Нідерландах; тут місце зірок займають сплячі коти.",
    quickrules_catplaces_1: "Постав кота в кожен рядок, кожен стовпець і кожну кімнату (ділянки всередині товстих ліній).",
