    game_rings: "Поверни кільця",
    home_rings_desc: "Від трьох до п'яти кілець одне в одному, на них фігури. Повертайте кільця, доки кожен промінь від центру не покаже однакову фігуру; на складному рівні кільце повертає й сусіда. Із найменшою кількістю ходів і кнопкою підказки.",
    rg_history_intro: "Кільця зі знаками, які повертають одне відносно одного, давні: Леон Баттіста Альберті 1467 року описав шифрувальний диск із двох обертових кілець. Головоломку тут створено для PaperGames.",
