    msg_t_rg_info: "Ходи: {n} · Найменше: {m}",
    game_matches: "Головоломки із сірниками",
    home_matches_desc: "Перекладіть один або два сірники, щоб неправильний приклад став правильним або щоб фігура мала потрібну кількість квадратів. 90 завдань на трьох рівнях, кожне перевірено комп'ютером; торкніться сірника, а потім вільного місця - без перетягування.",
    mt_history_intro: "Сірники стали звичною річчю в XIX столітті, а згодом і матеріалом для головоломок: у книжці Professor Hoffmann «Puzzles Old and New» (1893) уже є розділ головоломок із сірниками.",
