    game_tangram: "Танграм",
    home_tangram_desc: "Заповни контур сімома класичними частинами: трикутниками, квадратом і паралелограмом. 90 контурів на чотирьох рівнях, кожен із розв'язком, перевіреним комп'ютером. У режимі «Лише контур» видно тільки зовнішню лінію, а частина лишається там, де ти торкнешся, - треба пробувати. Торкнися частини, поверни її, торкнися місця - без перетягування.",
    tg_history_intro: "Сім деталей, вирізаних із квадрата: головоломка походить із Китаю, де 1813 року надрукували найдавнішу збережену книжку про неї; від 1817 року вона стала справжнім захопленням у Європі.",
    quickrules_tangram_1: "Виберіть деталь під контуром, поверніть її кнопкою «Повернути на 45°» або віддзеркальте, а потім торкніться місця, куди вона має лягти.",
